 1→import { cn } from '@tpmjs/utils/cn';
 2→import { forwardRef } from 'react';
 3→import { type IconName, icons } from './icons';
 4→import type { IconProps } from './types';
 5→import { iconVariants } from './variants';
 6→
 7→export type { IconName };
 8→
 9→/**
10→ * Icon component
11→ *
12→ * Renders SVG icons with consistent sizing and styling.
13→ * Icons inherit text color via currentColor.
14→ *
15→ * @example
16→ * ```tsx
17→ * import { Icon } from '@tpmjs/ui/Icon/Icon';
18→ *
19→ * function MyComponent() {
20→ *   return <Icon icon="github" size="md" className="text-zinc-400" />;
21→ * }
22→ * ```
23→ */
24→export const Icon = forwardRef<SVGSVGElement, IconProps>(
25→  ({ className, icon, size = 'md', ...props }, ref) => {
26→    const iconData = icons[icon];
27→
28→    if (!iconData) {
29→      return null;
30→    }
31→
32→    return (
33→      <svg
34→        ref={ref}
35→        className={cn(
36→          iconVariants({
37→            size,
38→          }),
39→          className
40→        )}
41→        viewBox={iconData.viewBox}
42→        fill="currentColor"
43→        aria-hidden={props['aria-hidden'] ?? true}
44→        {...props}
45→      >
46→        <path d={iconData.path} />
47→      </svg>
48→    );
49→  }
50→);
51→
52→Icon.displayName = 'Icon';
