 1→import { cn } from '@tpmjs/utils/cn';
 2→import { forwardRef } from 'react';
 3→import type { Tab, TabsProps } from './types';
 4→import { tabButtonVariants, tabCountVariants, tabsContainerVariants } from './variants';
 5→
 6→// Re-export types for consumers
 7→export type { Tab, TabsProps };
 8→
 9→/**
10→ * Tabs component
11→ *
12→ * Displays a horizontal list of tabs with optional count badges.
13→ * Supports keyboard navigation and accessibility.
14→ *
15→ * @example
16→ * ```tsx
17→ * import { Tabs } from '@tpmjs/ui/Tabs/Tabs';
18→ * import { useState } from 'react';
19→ *
20→ * function MyComponent() {
21→ *   const [activeTab, setActiveTab] = useState('all');
22→ *
23→ *   return (
24→ *     <Tabs
25→ *       tabs={[
26→ *         { id: 'all', label: 'All Tools', count: 1234 },
27→ *         { id: 'featured', label: 'Featured', count: 42 },
28→ *       ]}
29→ *       activeTab={activeTab}
30→ *       onTabChange={setActiveTab}
31→ *       size="md"
32→ *     />
33→ *   );
34→ * }
35→ * ```
36→ */
37→export const Tabs = forwardRef<HTMLDivElement, TabsProps>(
38→  (
39→    { className, tabs, activeTab, onTabChange, size = 'md', variant = 'default', ...props },
40→    ref
41→  ) => {
42→    return (
43→      <div
44→        className={cn(
45→          tabsContainerVariants({
46→            size,
47→            variant,
48→          }),
49→          className
50→        )}
51→        role="tablist"
52→        ref={ref}
53→        {...props}
54→      >
55→        {tabs.map((tab) => {
56→          const isActive = tab.id === activeTab;
57→
58→          return (
59→            <button
60→              key={tab.id}
61→              type="button"
62→              role="tab"
63→              aria-selected={isActive}
64→              aria-controls={`tabpanel-${tab.id}`}
65→              id={`tab-${tab.id}`}
66→              className={tabButtonVariants({
