609→              conversations.map((conv) => (
610→                <button
611→                  type="button"
612→                  key={conv.id}
613→                  onClick={() => handleSelectConversation(conv.slug)}
614→                  className={`w-full text-left p-2 mb-1 rounded border border-transparent transition-colors ${
615→                    chatId === conv.slug
616→                      ? 'bg-primary/10 border-primary/20 text-primary'
617→                      : 'text-foreground-secondary hover:bg-surface-secondary hover:border-border'
618→                  }`}
619→                >
620→                  <p className="text-sm font-medium truncate">{conv.title || 'Untitled Chat'}</p>
621→                  <p className="text-[10px] text-foreground-tertiary font-mono mt-0.5">
622→                    {conv.messageCount} messages
623→                  </p>
624→                </button>
625→              ))
626→            )}
627→          </div>
628→        </div>
629→
630→        {/* Chat Area */}
631→        <div className="flex-1 flex flex-col min-w-0">
632→          {/* Messages */}
633→          <div className="flex-1 overflow-y-auto p-4 space-y-4">
634→            {messages.length === 0 && !streamingContent && (
635→              <div className="flex items-center justify-center h-full">
636→                <fieldset className="border border-dashed border-border p-8 max-w-md text-center">
637→                  <legend className="px-2 font-mono text-xs text-foreground-tertiary lowercase">
638→                    new conversation
639→                  </legend>
640→                  <div className="w-14 h-14 rounded-full bg-primary/10 flex items-center justify-center mx-auto mb-4">
641→                    <Icon icon="message" size="lg" className="text-primary" />
642→                  </div>
643→                  <h3 className="font-mono text-foreground mb-2 lowercase">start chatting</h3>
644→                  <p className="text-sm text-foreground-secondary">
645→                    Send a message to start a conversation with {agent.name}.
646→                  </p>
647→                </fieldset>
648→              </div>
649→            )}
650→
651→            {(() => {
652→              // Build a map of toolCallId -> tool result from TOOL messages
653→              const toolResultsMap = new Map<string, unknown>();
654→              for (const msg of messages) {
655→                if (msg.role === 'TOOL' && msg.toolCallId) {
656→                  let output: unknown;
657→                  if (msg.toolResult) {
658→                    output = msg.toolResult;
659→                  } else {
660→                    try {
661→                      output = JSON.parse(msg.content || '{}');
662→                    } catch {
663→                      output = { result: msg.content };
664→                    }
665→                  }
666→                  toolResultsMap.set(msg.toolCallId, output);
667→                }
668→              }
669→
670→              return messages.map((message) => {
671→                const hasEmbeddedToolCalls =
672→                  message.role === 'ASSISTANT' &&
673→                  message.toolCalls &&
674→                  Array.isArray(message.toolCalls) &&
675→                  message.toolCalls.length > 0;
676→
677→                return (
678→                  <div key={message.id} className="space-y-2">
679→                    {/* Render embedded tool calls from ASSISTANT messages */}
680→                    {hasEmbeddedToolCalls && (
681→                      <div className="space-y-2">
682→                        {message.toolCalls?.map((tc) => {
683→                          const toolOutput = toolResultsMap.get(tc.toolCallId);
684→                          const hasOutput = toolOutput !== undefined;
685→
686→                          return (
687→                            <div key={tc.toolCallId} className="flex justify-start">
688→                              <div className="max-w-[85%]">
689→                                <ToolCallCard
690→                                  toolCall={{
691→                                    toolCallId: tc.toolCallId,
692→                                    toolName: tc.toolName,
693→                                    input: tc.args,
694→                                    output: toolOutput,
695→                                    status: hasOutput ? 'success' : 'pending',
696→                                  }}
697→                                  isExpanded={expandedToolCalls.has(tc.toolCallId)}
698→                                  onToggle={() => toggleToolCall(tc.toolCallId)}
699→                                />
700→                              </div>
701→                            </div>
702→                          );
703→                        })}
704→                      </div>
705→                    )}
706→
707→                    {/* Render the message content - skip TOOL messages */}
708→                    {message.role !== 'TOOL' && (
709→                      <div
710→                        className={`flex ${message.role === 'USER' ? 'justify-end' : 'justify-start'}`}
711→                      >
712→                        <div
713→                          className={`max-w-[85%] rounded-lg p-4 ${
714→                            message.role === 'USER'
715→                              ? 'bg-primary text-primary-foreground'
716→                              : 'bg-surface text-foreground border border-dashed border-border'
717→                          }`}
718→                        >
719→                          {message.role === 'USER' ? (
720→                            <div className="text-sm whitespace-pre-wrap">{message.content}</div>
721→                          ) : (
722→                            <div className="text-sm prose prose-sm dark:prose-invert max-w-none">
723→                              <Streamdown>{message.content}</Streamdown>
724→                            </div>
725→                          )}
726→                        </div>
727→                      </div>
728→                    )}
729→                  </div>
730→                );
731→              });
732→            })()}
733→
734→            {/* Live tool calls during streaming */}
735→            {toolCalls.length > 0 && (
736→              <div className="space-y-2">
737→                {toolCalls.map((tc) => (
738→                  <div key={tc.toolCallId} className="flex justify-start">
739→                    <div className="max-w-[85%]">
740→                      <ToolCallCard
741→                        toolCall={tc}
742→                        isExpanded={expandedToolCalls.has(tc.toolCallId)}
743→                        onToggle={() => toggleToolCall(tc.toolCallId)}
744→                      />
745→                    </div>
746→                  </div>
747→                ))}
748→              </div>
749→            )}
750→
751→            {streamingContent && (
752→              <div className="flex justify-start">
753→                <div className="max-w-[85%] rounded-lg p-4 bg-surface border border-dashed border-border">
754→                  <div className="text-sm prose prose-sm dark:prose-invert max-w-none">
755→                    <Streamdown>{streamingContent}</Streamdown>
756→                  </div>
757→                  <span className="inline-block w-2 h-4 bg-primary animate-pulse ml-1" />
758→                </div>
759→              </div>
760→            )}
761→
762→            {isSending && !streamingContent && toolCalls.length === 0 && (
763→              <div className="flex justify-start">
764→                <div className="rounded-lg p-4 bg-surface border border-dashed border-border">
765→                  <div className="flex items-center gap-2 text-foreground-secondary">
766→                    <Icon icon="loader" size="sm" className="animate-spin" />
767→                    <span className="text-sm font-mono lowercase">thinking...</span>
768→                  </div>
769→                </div>
770→              </div>
771→            )}
772→
773→            <div ref={messagesEndRef} />
774→          </div>
775→
776→          {/* Error Message */}
