150→function WriteFileEntry({ entry }: { entry: SandboxLogEntry }) {
151→  const path = (entry.toolInput?.path as string) || (entry.toolResult?.path as string) || '';
152→  const success = entry.toolResult?.success as boolean | undefined;
153→  const bytesWritten = entry.toolResult?.bytesWritten as number | undefined;
154→
155→  return (
156→    <div className="flex items-center justify-between gap-2">
