173→
174→function ListFilesEntry({
175→  entry,
176→  expanded,
177→  onToggle,
178→}: {
179→  entry: SandboxLogEntry;
180→  expanded: boolean;
181→  onToggle: () => void;
182→}) {
183→  const path = (entry.toolInput?.path as string) || (entry.toolInput?.directory as string) || '.';
184→  const entries =
