 68→    obj.success === false ||
 69→    obj.error !== undefined ||
 70→    obj.__tpmjs_error__ !== undefined ||
 71→    (typeof obj.message === 'string' && obj.message.toLowerCase().includes('error'))
 72→  );
 73→}
 74→
 75→/**
 76→ * Extract error message from tool output
 77→ */
 78→function getErrorMessage(output: unknown): string | null {
 79→  if (!output || typeof output !== 'object') return null;
 80→  const obj = output as Record<string, unknown>;
 81→  if (typeof obj.error === 'string') return obj.error;
 82→  if (typeof obj.__tpmjs_error__ === 'string') return obj.__tpmjs_error__;
 83→  if (obj.success === false && typeof obj.message === 'string') return obj.message;
 84→  return null;
 85→}
