 87→/**
 88→ * Tool call card with style guide aesthetics
 89→ */
 90→function ToolCallCard({
 91→  toolCall,
 92→  isExpanded,
 93→  onToggle,
 94→}: {
 95→  toolCall: ToolCall;
 96→  isExpanded: boolean;
 97→  onToggle: () => void;
 98→}) {
 99→  const hasError = Boolean(toolCall.output && isToolError(toolCall.output));
100→  const errorMessage = hasError ? getErrorMessage(toolCall.output) : null;
101→  const effectiveStatus = hasError ? 'error' : toolCall.status;
102→
103→  const statusColors = {
104→    pending: 'bg-warning/10 text-warning border-warning/30',
105→    running: 'bg-info/10 text-info border-info/30',
106→    success: 'bg-success/10 text-success border-success/30',
107→    error: 'bg-error/10 text-error border-error/30',
108→  };
109→
110→  const statusIcons: Record<ToolCall['status'], 'loader' | 'check' | 'alertCircle' | 'info'> = {
111→    pending: 'info',
112→    running: 'loader',
113→    success: 'check',
114→    error: 'alertCircle',
115→  };
116→
117→  const formatJson = (data: unknown): React.ReactNode => {
118→    try {
119→      return JSON.stringify(data, null, 2);
120→    } catch {
121→      return String(data);
122→    }
123→  };
124→
125→  return (
126→    <fieldset
