641→            )}
642→          </div>
643→        </div>
644→
645→        {/* Chat Area */}
646→        <div className="flex-1 flex flex-col min-w-0">
647→          {/* Messages */}
648→          <div className="flex-1 overflow-y-auto p-4 space-y-4">
649→            {messages.length === 0 && !streamingContent && (
650→              <div className="flex items-center justify-center h-full">
651→                <fieldset className="border border-dashed border-border p-8 max-w-md text-center">
652→                  <legend className="px-2 font-mono text-xs text-foreground-tertiary lowercase">
653→                    new conversation
654→                  </legend>
655→                  <div className="w-14 h-14 rounded-full bg-primary/10 flex items-center justify-center mx-auto mb-4">
656→                    <Icon icon="message" size="lg" className="text-primary" />
657→                  </div>
658→                  <h3 className="font-mono text-foreground mb-2 lowercase">start chatting</h3>
659→                  <p className="text-sm text-foreground-secondary">
660→                    Send a message to start a conversation with {agent.name}.
661→                  </p>
662→                </fieldset>
663→              </div>
