692→                return (
693→                  <div key={message.id} className="space-y-2">
694→                    {/* Render embedded tool calls from ASSISTANT messages */}
695→                    {hasEmbeddedToolCalls && (
696→                      <div className="space-y-2">
697→                        {message.toolCalls?.map((tc) => {
698→                          const toolOutput = toolResultsMap.get(tc.toolCallId);
699→                          const hasOutput = toolOutput !== undefined;
