  6→
  7→export interface ToolParameter {
  8→  name: string;
  9→  type: string;
 10→  description: string;
 11→  required: boolean;
 12→  default?: unknown;
 13→}
 14→
 15→export interface ToolInfo {
 16→  id: string;
 17→  toolId: string;
 18→  tool: {
 19→    id: string;
 20→    name: string;
 21→    description: string | null;
 22→    parameters: ToolParameter[] | null;
 23→    package: {
 24→      npmPackageName: string;
 25→      category: string;
 26→    };
 27→  };
 28→}
 29→
 30→export interface CollectionInfo {
 31→  id: string;
 32→  collectionId: string;
 33→  collection: {
 34→    id: string;
 35→    name: string;
 36→    toolCount: number;
 37→  };
 38→}
 39→
 40→interface CollectionToolData {
 41→  tools: ToolInfo[];
 42→  loading: boolean;
 43→  error: string | null;
 44→}
 45→
 46→interface ChatToolsPanelProps {
 47→  tools: ToolInfo[];
 48→  collections: CollectionInfo[];
 49→  isOpen: boolean;
 50→  onClose: () => void;
 51→  onToolClick: (tool: ToolInfo) => void;
