 54→export function ChatToolsPanel({
 55→  tools,
 56→  collections,
 57→  isOpen,
 58→  onClose,
 59→  onToolClick,
 60→}: ChatToolsPanelProps) {
 61→  const [expandedCollections, setExpandedCollections] = useState<Set<string>>(new Set());
 62→  const [collectionTools, setCollectionTools] = useState<Record<string, CollectionToolData>>({});
 63→
 64→  const fetchCollectionTools = useCallback(
 65→    async (collectionId: string) => {
 66→      const existingData = collectionTools[collectionId];
 67→      if (existingData?.tools && existingData.tools.length > 0) return;
 68→
 69→      setCollectionTools((prev) => ({
 70→        ...prev,
 71→        [collectionId]: { tools: [], loading: true, error: null },
 72→      }));
 73→
 74→      try {
 75→        const response = await fetch(`/api/collections/${collectionId}/tools`);
 76→        const data = await response.json();
 77→
 78→        if (data.success) {
 79→          // Transform the response to match ToolInfo structure
 80→          const transformedTools: ToolInfo[] = (data.data || []).map(
 81→            (ct: { id: string; toolId: string; tool: ToolInfo['tool'] }) => ({
 82→              id: ct.id,
 83→              toolId: ct.toolId,
 84→              tool: ct.tool,
 85→            })
 86→          );
 87→          setCollectionTools((prev) => ({
 88→            ...prev,
 89→            [collectionId]: { tools: transformedTools, loading: false, error: null },
 90→          }));
 91→        } else {
 92→          setCollectionTools((prev) => ({
 93→            ...prev,
 94→            [collectionId]: { tools: [], loading: false, error: data.error || 'Failed to load' },
 95→          }));
 96→        }
 97→      } catch {
 98→        setCollectionTools((prev) => ({
 99→          ...prev,
100→          [collectionId]: { tools: [], loading: false, error: 'Failed to load tools' },
101→        }));
102→      }
103→    },
104→    [collectionTools]
105→  );
106→
107→  const toggleCollection = (collectionId: string) => {
108→    setExpandedCollections((prev) => {
109→      const next = new Set(prev);
110→      if (next.has(collectionId)) {
111→        next.delete(collectionId);
112→      } else {
113→        next.add(collectionId);
114→        // Fetch tools when expanding
115→        fetchCollectionTools(collectionId);
116→      }
117→      return next;
118→    });
119→  };
120→
121→  if (!isOpen) return null;
122→
123→  const totalToolsFromCollections = collections.reduce((acc, c) => acc + c.collection.toolCount, 0);
124→
125→  return (
126→    <div className="w-72 border-l border-dashed border-border flex flex-col bg-surface">
127→      {/* header */}
128→      <div className="flex items-center justify-between p-4 border-b border-dashed border-border">
