134→        </Button>
135→      </div>
136→
137→      {/* tools list */}
138→      <div className="flex-1 overflow-y-auto">
139→        {/* direct tools */}
140→        {tools.length > 0 && (
141→          <fieldset className="m-3 border border-dashed border-border">
142→            <legend className="px-2 font-mono text-xs text-foreground-tertiary lowercase">
143→              direct tools ({tools.length})
144→            </legend>
145→            <div className="p-2 space-y-1">
146→              {tools.map((t) => (
147→                <button
148→                  key={t.id}
149→                  type="button"
150→                  onClick={() => onToolClick(t)}
151→                  className="w-full text-left p-2 rounded hover:bg-primary/5 hover:border-primary/20 border border-transparent transition-colors group"
152→                >
153→                  <div className="flex items-start gap-2">
154→                    <div className="w-1.5 h-1.5 rounded-full bg-primary mt-1.5 flex-shrink-0" />
155→                    <div className="min-w-0 flex-1">
156→                      <p className="font-mono text-sm text-foreground truncate group-hover:text-primary transition-colors">
157→                        {t.tool.name}
158→                      </p>
159→                      <p className="font-mono text-xs text-foreground-tertiary truncate">
160→                        {t.tool.package.npmPackageName}
161→                      </p>
162→                      {t.tool.description && (
163→                        <p className="text-xs text-foreground-secondary mt-0.5 line-clamp-2">
164→                          {t.tool.description}
165→                        </p>
166→                      )}
167→                    </div>
168→                  </div>
169→                </button>
170→              ))}
171→            </div>
172→          </fieldset>
173→        )}
174→
175→        {/* collections */}
176→        {collections.length > 0 && (
177→          <fieldset className="m-3 border border-dashed border-border">
178→            <legend className="px-2 font-mono text-xs text-foreground-tertiary lowercase">
179→              from collections ({totalToolsFromCollections})
180→            </legend>
181→            <div className="p-2 space-y-2">
182→              {collections.map((c) => {
183→                const isExpanded = expandedCollections.has(c.collectionId);
184→                const toolData = collectionTools[c.collectionId];
185→
186→                return (
187→                  <div
188→                    key={c.id}
189→                    className="border border-dashed border-border/50 rounded bg-surface-secondary/30 overflow-hidden"
190→                  >
191→                    {/* collection header - clickable */}
192→                    <button
193→                      type="button"
194→                      onClick={() => toggleCollection(c.collectionId)}
195→                      className="w-full p-2 flex items-center gap-2 hover:bg-surface-secondary transition-colors"
196→                    >
197→                      <Icon
198→                        icon="chevronRight"
199→                        size="xs"
200→                        className={`text-foreground-tertiary transition-transform ${isExpanded ? 'rotate-90' : ''}`}
201→                      />
202→                      <Icon icon="folder" size="xs" className="text-foreground-tertiary" />
203→                      <span className="font-mono text-xs text-foreground truncate flex-1 text-left">
204→                        {c.collection.name}
205→                      </span>
206→                      <span className="text-[10px] text-foreground-tertiary">
207→                        {c.collection.toolCount}
208→                      </span>
209→                    </button>
210→
211→                    {/* expanded tools */}
212→                    {isExpanded && (
213→                      <div className="border-t border-dashed border-border/50">
214→                        {toolData?.loading ? (
215→                          <div className="p-3 flex items-center justify-center gap-2">
216→                            <Icon
217→                              icon="loader"
218→                              size="xs"
219→                              className="animate-spin text-foreground-tertiary"
220→                            />
221→                            <span className="text-xs text-foreground-tertiary">loading...</span>
222→                          </div>
223→                        ) : toolData?.error ? (
224→                          <div className="p-3 text-xs text-error text-center">{toolData.error}</div>
225→                        ) : toolData?.tools.length === 0 ? (
226→                          <div className="p-3 text-xs text-foreground-tertiary text-center">
227→                            no tools in collection
228→                          </div>
229→                        ) : (
230→                          <div className="p-2 space-y-1 max-h-64 overflow-y-auto">
231→                            {toolData?.tools.map((t) => (
232→                              <button
233→                                key={t.id}
234→                                type="button"
235→                                onClick={() => onToolClick(t)}
236→                                className="w-full text-left p-2 rounded hover:bg-primary/5 border border-transparent hover:border-primary/20 transition-colors group"
237→                              >
238→                                <div className="flex items-start gap-2">
239→                                  <div className="w-1.5 h-1.5 rounded-full bg-primary/50 mt-1.5 flex-shrink-0" />
240→                                  <div className="min-w-0 flex-1">
241→                                    <p className="font-mono text-xs text-foreground truncate group-hover:text-primary transition-colors">
242→                                      {t.tool.name}
243→                                    </p>
244→                                    {t.tool.description && (
245→                                      <p className="text-[10px] text-foreground-tertiary mt-0.5 line-clamp-1">
246→                                        {t.tool.description}
247→                                      </p>
248→                                    )}
249→                                  </div>
250→                                </div>
251→                              </button>
252→                            ))}
253→                          </div>
254→                        )}
255→                      </div>
256→                    )}
257→                  </div>
258→                );
259→              })}
260→            </div>
261→          </fieldset>
262→        )}
263→
264→        {/* empty state */}
265→        {tools.length === 0 && collections.length === 0 && (
266→          <div className="p-6 text-center">
267→            <div className="w-10 h-10 rounded-full bg-surface-secondary flex items-center justify-center mx-auto mb-3">
268→              <Icon icon="puzzle" size="sm" className="text-foreground-tertiary" />
269→            </div>
