  1→'use client';
  2→
  3→import { Button } from '@tpmjs/ui/Button/Button';
  4→import { Icon } from '@tpmjs/ui/Icon/Icon';
  5→import { useCallback, useEffect, useRef, useState } from 'react';
  6→import { logsToJson, type SandboxLogEntry, SandboxTerminal } from './SandboxLogEntries';
  7→
  8→const PAGE_SIZE = 50;
  9→
 10→export function ConversationSandboxLogs({
 11→  agentId,
 12→  conversationSlug,
 13→  isOpen,
 14→  onClose,
 15→}: {
 16→  agentId: string;
 17→  conversationSlug: string;
 18→  isOpen: boolean;
 19→  onClose: () => void;
 20→}) {
 21→  const [logs, setLogs] = useState<SandboxLogEntry[]>([]);
 22→  const [isLoading, setIsLoading] = useState(true);
 23→  const [hasMore, setHasMore] = useState(false);
 24→  const [isLoadingMore, setIsLoadingMore] = useState(false);
 25→  const [autoRefresh, setAutoRefresh] = useState(false);
 26→  const [copied, setCopied] = useState(false);
 27→  const intervalRef = useRef<ReturnType<typeof setInterval> | null>(null);
 28→
 29→  const fetchLogs = useCallback(
 30→    async (offset = 0, append = false) => {
 31→      if (!conversationSlug) return;
 32→      try {
 33→        const res = await fetch(
 34→          `/api/agents/${agentId}/logs?sandbox=true&conversation=${encodeURIComponent(conversationSlug)}&limit=${PAGE_SIZE}&offset=${offset}`
 35→        );
 36→        const json = await res.json();
 37→        if (json.success) {
 38→          const newLogs = json.data.logs as SandboxLogEntry[];
 39→          setLogs((prev) => (append ? [...prev, ...newLogs] : newLogs));
 40→          setHasMore(json.data.pagination.hasMore);
 41→        }
 42→      } catch (err) {
 43→        console.error('Failed to fetch conversation sandbox logs:', err);
 44→      } finally {
 45→        setIsLoading(false);
 46→      }
 47→    },
 48→    [agentId, conversationSlug]
 49→  );
 50→
 51→  // Fetch when opened or conversation changes
 52→  useEffect(() => {
 53→    if (isOpen) {
 54→      setIsLoading(true);
 55→      setLogs([]);
 56→      fetchLogs();
 57→    }
 58→  }, [isOpen, fetchLogs]);
 59→
 60→  // Auto-refresh
 61→  useEffect(() => {
 62→    if (autoRefresh && isOpen) {
 63→      intervalRef.current = setInterval(() => fetchLogs(), 5000);
 64→    }
 65→    return () => {
 66→      if (intervalRef.current) clearInterval(intervalRef.current);
 67→    };
 68→  }, [autoRefresh, isOpen, fetchLogs]);
 69→
 70→  const loadMore = async () => {
 71→    setIsLoadingMore(true);
 72→    await fetchLogs(logs.length, true);
 73→    setIsLoadingMore(false);
 74→  };
 75→
 76→  const copyJson = async () => {
 77→    await navigator.clipboard.writeText(logsToJson(logs));
 78→    setCopied(true);
 79→    setTimeout(() => setCopied(false), 2000);
 80→  };
 81→
 82→  if (!isOpen) return null;
 83→
 84→  return (
 85→    <div className="w-80 border-l border-dashed border-border flex flex-col bg-surface hidden lg:flex">
 86→      {/* Header */}
 87→      <div className="p-3 border-b border-dashed border-border flex items-center justify-between">
 88→        <span className="font-mono text-xs text-foreground-tertiary lowercase">sandbox logs</span>
 89→        <div className="flex items-center gap-1">
 90→          {logs.length > 0 && (
 91→            <Button size="sm" variant="ghost" onClick={copyJson} title="Copy all as JSON">
 92→              <Icon icon={copied ? 'check' : 'copy'} size="xs" />
 93→            </Button>
 94→          )}
 95→          <button
 96→            type="button"
 97→            onClick={() => setAutoRefresh(!autoRefresh)}
 98→            className={`flex items-center gap-1 text-[10px] font-mono px-1.5 py-0.5 rounded border transition-colors ${
 99→              autoRefresh
100→                ? 'border-success/50 text-success bg-success/10'
101→                : 'border-border text-foreground-tertiary hover:text-foreground-secondary'
102→            }`}
103→          >
104→            <span
105→              className={`inline-block w-1.5 h-1.5 rounded-full ${autoRefresh ? 'bg-success animate-pulse' : 'bg-foreground-tertiary'}`}
106→            />
107→            {autoRefresh ? 'live' : 'paused'}
108→          </button>
109→          <Button size="sm" variant="ghost" onClick={onClose} title="Close">
110→            <Icon icon="x" size="xs" />
111→          </Button>
112→        </div>
113→      </div>
114→
115→      {/* Content */}
116→      <div className="flex-1 overflow-y-auto p-2">
117→        {isLoading ? (
118→          <div className="flex items-center justify-center py-8">
119→            <Icon icon="loader" size="sm" className="animate-spin text-foreground-tertiary" />
120→          </div>
121→        ) : logs.length === 0 ? (
122→          <div className="text-center py-8">
123→            <Icon icon="terminal" size="md" className="mx-auto text-foreground-tertiary mb-2" />
124→            <p className="text-xs text-foreground-tertiary font-mono">no sandbox logs yet</p>
125→          </div>
126→        ) : (
127→          <>
128→            <SandboxTerminal logs={logs} showConversation={false} />
129→            {hasMore && (
130→              <div className="flex justify-center py-2">
131→                <Button variant="ghost" size="sm" onClick={loadMore} disabled={isLoadingMore}>
132→                  {isLoadingMore ? 'Loading...' : 'Load more'}
133→                </Button>
134→              </div>
135→            )}
136→          </>
137→        )}
138→      </div>
139→    </div>
140→  );
141→}
