'use client';

import { useCallback, useEffect, useRef, useState } from 'react';

const MIN_WIDTH = 200;
const MAX_WIDTH = 600;

/**
 * Hook for making a panel horizontally resizable with localStorage persistence.
 * The drag handle should be placed on the left edge of the panel.
 *
 * @param storageKey - localStorage key for persisting width
 * @param defaultWidth - default width in pixels
 * @returns { width, handleProps } - width to apply as inline style, props to spread on the drag handle element
 */
export function useResizableWidth(storageKey: string, defaultWidth: number) {
  const [width, setWidth] = useState(defaultWidth);
  const isDragging = useRef(false);
  const startX = useRef(0);
  const startWidth = useRef(0);

  // Load from localStorage on mount
  useEffect(() => {
    try {
      const stored = localStorage.getItem(storageKey);
      if (stored) {
        const parsed = Number.parseInt(stored, 10);
        if (parsed >= MIN_WIDTH && parsed <= MAX_WIDTH) {
          setWidth(parsed);
        }
      }
    } catch {
      // ignore localStorage errors
    }
  }, [storageKey]);

  const onMouseDown = useCallback(
    (e: React.MouseEvent) => {
      e.preventDefault();
      isDragging.current = true;
      startX.current = e.clientX;
      startWidth.current = width;
      document.body.style.cursor = 'col-resize';
      document.body.style.userSelect = 'none';

      const onMouseMove = (ev: MouseEvent) => {
        if (!isDragging.current) return;
        // Dragging left edge: moving left increases width, moving right decreases
        const delta = startX.current - ev.clientX;
        const newWidth = Math.min(MAX_WIDTH, Math.max(MIN_WIDTH, startWidth.current + delta));
        setWidth(newWidth);
      };

      const onMouseUp = () => {
        isDragging.current = false;
        document.body.style.cursor = '';
        document.body.style.userSelect = '';
        document.removeEventListener('mousemove', onMouseMove);
        document.removeEventListener('mouseup', onMouseUp);

        // Persist to localStorage
        try {
          const delta = startX.current - 0; // just save current width
          const finalWidth = Math.min(
            MAX_WIDTH,
            Math.max(MIN_WIDTH, startWidth.current + (startX.current - (document as unknown as { _lastX?: number })._lastX || startX.current))
          );
          // Actually just read the latest width from state won't work in closure,
          // so compute it from the last mousemove
        } catch {
          // ignore
        }
      };

      // Better approach: persist on mouseup using a ref
      const onMouseUpFinal = (ev: MouseEvent) => {
        isDragging.current = false;
        document.body.style.cursor = '';
        document.body.style.userSelect = '';
        document.removeEventListener('mousemove', onMouseMove);
        document.removeEventListener('mouseup', onMouseUpFinal);

        const delta = startX.current - ev.clientX;
        const finalWidth = Math.min(MAX_WIDTH, Math.max(MIN_WIDTH, startWidth.current + delta));
        try {
          localStorage.setItem(storageKey, String(finalWidth));
        } catch {
          // ignore
        }
      };

      // Remove the bad handler, use the good one
      document.addEventListener('mousemove', onMouseMove);
      document.addEventListener('mouseup', onMouseUpFinal);
    },
    [width, storageKey]
  );

  const handleProps = {
    onMouseDown,
    className:
      'absolute left-0 top-0 bottom-0 w-1.5 cursor-col-resize hover:bg-primary/20 active:bg-primary/30 transition-colors z-10',
  };

  return { width, handleProps };
}

