{
  "id": "cmlppfpjp0005jp0463lnnrqn",
  "content": {
    "date": "2026-02-17",
    "feature": "Sandbox Logs",
    "summary": "Built a full sandbox logs feature for the TPMJS agent platform",
    "components": {
      "api": {
        "file": "apps/web/src/app/api/agents/[id]/logs/route.ts",
        "changes": "Added sandbox=true query param that filters for sandbox tool names (shellExec, readFile, writeFile, listFiles), returns full toolResult and toolInput JSON. Optional &conversation=slug filtering. Uses two separate Prisma queries: one for TOOL messages, one for ASSISTANT messages to extract toolInput via toolCallId matching."
      },
      "chatPage": {
        "file": "apps/web/src/app/dashboard/agents/[id]/chat/[chatId]/page.tsx",
        "changes": "Added Sandbox button next to Settings in header. Opens ConversationSandboxLogs side panel filtered by conversation slug."
      },
      "chatToolsPanel": {
        "file": "apps/web/src/components/agents/ChatToolsPanel.tsx",
        "changes": "Made horizontally resizable using useResizableWidth hook."
      },
      "agentDetailPage": {
        "file": "apps/web/src/app/dashboard/agents/[id]/page.tsx",
        "changes": "Added 'sandbox-logs' tab to PageTabId union and VALID_TABS. Conditionally shown when agent.sandboxEnabled is true. Renders SandboxLogsPanel component."
      },
      "sandboxLogsPanel": {
        "file": "apps/web/src/components/SandboxLogsPanel.tsx",
        "description": "Agent-level panel showing all sandbox logs across conversations. Fetch, pagination, auto-refresh toggle, Copy JSON button."
      },
      "sandboxLogEntries": {
        "file": "apps/web/src/components/SandboxLogEntries.tsx",
        "exports": [
          "SandboxLogEntry (interface)",
          "logsToJson (function)",
          "SandboxTerminal (component)"
        ],
        "description": "Terminal-style rendering with dark theme (#0d1117), macOS window chrome dots, color-coded commands: green $ for shellExec, blue cat for readFile, purple write for writeFile, orange ls for listFiles. No per-entry scroll constraints."
      },
      "useResizableWidth": {
        "file": "apps/web/src/hooks/useResizableWidth.ts",
        "description": "Hook for horizontally resizable panels. Drag handle on left edge, 200-600px range, persists width to localStorage. Keys: 'sandbox-logs-width' (default 320), 'tools-panel-width' (default 288)."
      },
      "conversationSandboxLogs": {
        "file": "apps/web/src/components/ConversationSandboxLogs.tsx",
        "description": "Per-conversation sidebar panel. Auto-refresh on by default (5s polling). Resizable via useResizableWidth hook."
      }
    },
    "keyDecisions": [
      "Used two separate Prisma queries for sandbox logs instead of complex OR filter (Prisma JSON null filter incompatibility)",
      "Auto-refresh defaults to on for conversation logs panel",
      "Terminal rendering uses hardcoded GitHub dark theme colors, not design system tokens",
      "Resizable panels use a custom hook rather than a library like react-resizable-panels"
    ]
  },
  "summary": "Sandbox Logs feature for TPMJS agents: terminal-style log viewer, per-conversation and agent-level panels, resizable side panels with localStorage persistence",
  "namespace": "tpmjs",
  "tags": [
    "tpmjs",
    "sandbox",
    "feature",
    "agents",
    "logs",
    "terminal",
    "resizable-panels"
  ],
